arguments.file_text:
@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the course catalog. Browse departments, explore courses, and submit your enrollment request.</p>

<h2 class="mt-4">Featured Courses</h2>
<div class="row">
    @foreach (var course in FeaturedCourses)
    {
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Code</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                    <p class="card-text">@course.Credits credits &middot; @course.DepartmentName</p>
                    <a href="courses/@course.Id" class="card-link">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-5">Departments</h2>
<div class="row">
    @foreach (var dept in Departments)
    {
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text">@dept.Description</p>
                    <a href="courses?departmentId=@dept.Id" class="card-link">Browse @dept.Code Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private IReadOnlyList<Course> FeaturedCourses { get; set; } = [];
    private IReadOnlyList<Department> Departments { get; set; } = [];

    protected override void OnInitialized()
    {
        FeaturedCourses = CatalogService.GetFeaturedCourses();
        Departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search" placeholder="Search by title, code, or instructor..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (Courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in Courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private IReadOnlyList<Course> Courses { get; set; } = [];
    private IReadOnlyList<Department> Departments { get; set; } = [];

    protected override void OnInitialized()
    {
        Departments = CatalogService.GetDepartments();
        Courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@SelectedCourseName</strong> has been received. You will be notified once it is processed.</p>
        <a href="courses" class="btn btn-primary mt-2">Back to Catalog</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <form method="post" @formname="enrollment">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
                    @if (ValidationErrors.ContainsKey(nameof(Model.StudentName)))
                    {
                        <div class="text-danger">@ValidationErrors[nameof(Model.StudentName)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" placeholder="e.g. ABC12345" required />
                    @if (ValidationErrors.ContainsKey(nameof(Model.StudentId)))
                    {
                        <div class="text-danger">@ValidationErrors[nameof(Model.StudentId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in AllCourses)
                        {
                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code – @course.Title</option>
                        }
                    </select>
                    @if (ValidationErrors.ContainsKey(nameof(Model.CourseId)))
                    {
                        <div class="text-danger">@ValidationErrors[nameof(Model.CourseId)]</div>
                    }
                </div>

                <button type="submit" class="btn btn-primary">Submit Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private IReadOnlyList<Course> AllCourses { get; set; } = [];
    private Dictionary<string, string> ValidationErrors { get; set; } = new();
    private bool Submitted { get; set; }
    private string SelectedCourseName { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        AllCourses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (!HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET"))
            return;

        ValidationErrors.Clear();
        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);

        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    ValidationErrors.TryAdd(member, result.ErrorMessage ?? "Invalid.");
                }
            }
            return;
        }

        if (CatalogService.SubmitEnrollmentRequest(Model))
